INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 3, 'theory', 'Quiz: conditions');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 3, 0, 'How does an equality check differ from assignment?', '["It does not, they are the same thing", "Assignment is one sign =, the check is two signs ==", "The check is one sign =, assignment is ==", "In Python the check is done with the word eq"]', 1, 'One sign means "put", two signs mean the question "are they equal". Mixing them up is a classic mistake.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 3, 1, 'Why does Python need indentation inside an if?', '["It is decoration for readability", "The code editor requires it", "Indentation is part of the language: it shows that the code belongs to the condition", "Indentation makes the program faster"]', 2, 'In Python indentation is syntax: the indented block runs when the condition is true.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 3, 2, 'In an if / elif / elif / else chain, how many branches run?', '["All those whose condition is true", "Exactly one: the first match", "The last match", "Two: the first and the last"]', 1, 'Checks go from top to bottom: the first suitable one runs, and the rest are not even considered.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 3, 3, 'The condition "temperature above 30 AND it is a weekend" is written in Python as…', '["t > 30 & weekend", "t > 30 and weekend", "t > 30 or weekend", "t > 30, weekend"]', 1, '"And" means both conditions are true; it is written with the word and.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 3, 4, 'What does the comparison 0 <= x <= 100 return when x = 50?', '["An error: you cannot write it like that", "False", "True: chained comparisons work as in math", "50"]', 2, 'A Python special feature: a chain of comparisons can be written as one expression, like at school.');
